import { useEffect } from 'react';

function MyComponent({ value }) {
  // Runs after every render
  useEffect(() => {
    console.log('Rendered');
  });

  // Runs only once — after the initial mount
  useEffect(() => {
    console.log('Mounted');
  }, []);

  // Runs when value changes
  useEffect(() => {
    console.log('Value changed:', value);
  }, [value]);
}

function Page({ title }) {
  useEffect(() => {
    document.title = title;
  }, [title]);

  return <h1>{title}</h1>;
}

// Usage
<Page title="Dashboard" />

function Timer() {
  const [count, setCount] = useState(0);

  // Stale closure — count is always 0 inside here
  useEffect(() => {
    const id = setInterval(() => {
      console.log(count); // Logs 0 forever
      setCount(count + 1); // Also uses stale count
    }, 1000);
    return () => clearInterval(id);
  }, []); // Missing count in deps

  return <p>{count}</p>;
}

// Fixed with functional update
useEffect(() => {
  const id = setInterval(() => {
    setCount((prev) => prev + 1);
  }, 1000);
  return () => clearInterval(id);
}, []);
